def factorial(n):
    if n == 0 or n == 1:
        return 1
    result = 1
    for i in range(2, n + 1):
        result = (result * i) % MOD
    return result

def inverse_modulo(a, mod=MOD):
    return pow(a, mod - 2, mod)

def combination(n, k):
    if k > n:
        return 0
    return (factorial(n) * inverse_modulo(factorial(k)) % MOD) * inverse_modulo(factorial(n - k)) % MOD

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    Q = int(data[1])
    A = list(map(int, data[2:N+2]))
    queries = [(int(data[N+2+2*i])-1, int(data[N+2+2*i+1])-1) for i in range(Q)]

    # Calculate prefix sums of A
    prefix_sum = [0] * (N + 1)
    for i in range(1, N + 1):
        prefix_sum[i] = (prefix_sum[i - 1] + A[i - 1]) % MOD

    # Calculate suffix sums of A
    suffix_sum = [0] * (N + 1)
    for i in range(N - 1, -1, -1):
        suffix_sum[i] = (suffix_sum[i + 1] + A[i]) % MOD

    results = []
    for u, v in queries:
