MOD = 998244353

def factorial(n):
    if n == 0 or n == 1:
        return 1
    result = 1
    for i in range(2, n + 1):
        result = (result * i) % MOD
    return result

def inverse_mod(a, m):
    return pow(a, m - 2, m)

def comb(n, k, mod):
    if k > n:
        return 0
    num = 1
    denom = 1
    for i in range(k):
        num = (num * (n - i)) % mod
        denom = (denom * (i + 1)) % mod
    return (num * inverse_mod(denom, mod)) % mod

def solve(N, Q, A, queries):
    def dfs(node, parent):
        nonlocal dp, subtree_size
        dp[node] = [0] * (N + 1)
        subtree_size[node] = 1
        for child in adj[node]:
            if child != parent:
                dfs(child, node)
                subtree_size[node] += subtree_size[child]
                for j in range(1, N + 1):
                    dp[node][j] = (dp[node][j] + dp[child][j] + dp[child][j - 1]) % MOD

    def update_dp(node, parent, add):
        nonlocal dp, subtree_size
        for j in range(1, N + 1):
            dp[node][j] = (dp[node][j] + add * j) % MOD
        for child in adj[node]:
            if child != parent:
                update_dp(child, node, add)

    adj = [[] for _ in range(N)]
    for i in range(1, N):
        adj[A[i]].append(i + 1)
        adj[i + 1].append(A[i])

    dp = [[0] * (N + 1) for _ in range(N)]
    subtree_size = [0] * N
    dfs(1, -1)

    results = []
    for u, v in queries:
        lca = u
        while u != v:
            if subtree_size[u] < subtree_size[v]:
                u, v = v, u
            u = A[u]
        dist_u = dp[u][subtree_size[lca]] + dp[lca][subtree_size[u]]
        dist_v = dp[v][subtree_size[lca]] + dp[lca][subtree_size[v]]
        result = (dist_u + dist_v - 2 * dp[lca][subtree_size[lca]]) % MOD
        results.append(result)

    return results

