class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        n = len(nums)
        best_product = -1

        # Iterate over all possible lengths of subsequences
        for length in range(1, n + 1):
            # Generate all combinations of indices for the current length
            for indices in itertools.combinations(range(n), length):
                # Calculate the alternating sum and product for this subsequence
                alt_sum = 0
                product = 1
                for i, index in enumerate(indices):
                    if i % 2 == 0:
                        alt_sum += nums[index]
                    else:
                        alt_sum -= nums[index]
                    product *= nums[index]
                    if product > limit:
                        break
                # Check if the alternating sum matches k and update the best product if it does
                if alt_sum == k and product <= limit:
                    best_product = max(best_product, product)

        return best_product
