class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        n = len(nums)
        dp = [[[-math.inf for _ in range(2)] for _ in range(n+1)] for _ in range(k+1)]

        # Initialize base case
        for i in range(n+1):
            dp[0][i][0] = 1

        for target in range(1, k+1):
            for length in range(1, n+1):
                for parity in range(2):
                    if parity == 0:
                        # Adding a positive number
                        for num in nums[:length]:
                            if dp[target-num][length-1][parity] != -math.inf and num + dp[target-num][length-1][parity] <= limit:
                                dp[target][length][parity] = max(dp[target][length][parity], num * dp[target-num][length-1][parity])
                    else:
                        # Subtracting a negative number (which is equivalent to adding a positive number)
                        for num in nums[:length]:
                            if dp[target+num][length-1][parity] != -math.inf and num - dp[target+num][length-1][parity] <= limit:
                                dp[target][length][parity] = max(dp[target][length][parity], num * dp[target+num][length-1][parity])

        result = -math.inf
        for length in range(1, n+1):
            result = max(result, dp[k][length][0], dp[k][length][1])

        return result if result != -math.inf else -1
