class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        # Initialize variables
        total_subarrays = n * (n + 1) // 2
        pairs_set = set(map(tuple, conflictingPairs))

        # Function to calculate subarrays without both elements of a pair
        def count_subarrays(pair):
            a, b = pair
            left = right = 0
            count = 0
            while left < n:
                if left + 1 == a and right + 1 == b:
                    count += (left - start) * (end - right)
                    start = left + 1
                    right = left + 1
                elif left + 1 == a:
                    start = left + 1
                elif right + 1 == b:
                    end = right + 1
                else:
                    right += 1
                left += 1
            return count

        # Calculate the maximum subarrays by removing each pair once
        max_subarrays = 0
        for pair in pairs_set:
            remaining_pairs = pairs_set - {pair}
            remaining_count = total_subarrays
            for rp in remaining_pairs:
                remaining_count -= count_subarrays(rp)
            max_subarrays = max(max_subarrays, remaining_count)

        return max_subarrays
