                        if last_a_index > last_b_index:
                            current_subarray_length = i - last_a_index
                        else:
                            current_subarray_length = i - last_b_index
                    elif last_a_index != -1:
                        # If only 'a' has been seen before
                        current_subarray_length = i - last_a_index
                    elif last_b_index != -1:
                        # If only 'b' has been seen before
                        current_subarray_length = i - last_b_index

                # Update the last seen index of 'a' or 'b'
                if i + 1 == a:
                    last_a_index = i
                elif i + 1 == b:
                    last_b_index = i

                # Count the total number of valid subarrays
                total_subarrays += current_subarray_length

            # Update the maximum number of subarrays found
            max_subarrays = max(max_subarrays, total_subarrays)

