import sys

def read_input():
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    M = int(data[1])

    edges = []
    for i in range(M):
        x = int(data[3 * i + 2]) - 1
        y = int(data[3 * i + 3]) - 1
        z = int(data[3 * i + 4])
        edges.append((x, y, z))

    return N, M, edges

def find_good_sequence(N, M, edges):
    # Initialize the sequence with zeros
    A = [0] * N

    # Process each edge to determine the value of A[x]
    for x, y, z in edges:
        # If A[y] is already determined, we can directly calculate A[x]
        if A[y] != 0:
            A[x] = A[y] ^ z
        else:
            # Otherwise, we need to check if we can set A[x] to minimize the sum
            # Let's assume A[x] = 0 and see if it leads to a contradiction
            if (A[x] := A[y] ^ z) < A[y]:
                continue
            else:
                # If setting A[x] = 0 leads to a contradiction, we need to backtrack
                # Let's try setting A[x] to the minimum possible value
                A[x] = min(A[y] ^ z, A[y])

    # Check if the sequence is valid
    for x, y, z in edges:
        if A[x] ^ A[y] != z:
            return -1

    return A

def main():
    N, M, edges = read_input()
    result = find_good_sequence(N, M, edges)
    if result == -1:
        print(-1)
    else:
        print(" ".join(map(str, result)))

