from collections import defaultdict, deque

def shortest_palindrome_path(N, grid):
    def is_palindrome(s):
        return s == s[::-1]

    def bfs(i, j):
        if grid[i][j] != '-':
            queue = deque([(i, j, grid[i][j], 0)])
        else:
            queue = deque([(i, j, '', 0)])

        visited = set()
        while queue:
            x, y, path, dist = queue.popleft()
            if (x, y, path) in visited:
                continue
            visited.add((x, y, path))

            if x == j and is_palindrome(path):
                return dist

            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < N and 0 <= ny < N and grid[nx][ny] != '-':
                    queue.append((nx, ny, path + grid[nx][ny], dist + 1))

        return -1

    result = [[0] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            result[i][j] = bfs(i, j)

    return result

# Read input
