from collections import defaultdict, deque

def shortest_palindrome_path(N, grid):
    def is_palindrome(s):
        return s == s[::-1]

    def bfs(start, end):
        if start == end:
            return 0
        queue = deque([(start, 0)])
        visited = set([start])
        while queue:
            current, length = queue.popleft()
            for neighbor in range(N):
                if grid[current][neighbor] != '-' and neighbor not in visited:
                    new_length = length + 1
                    if neighbor == end:
                        return new_length
                    new_string = grid[current][neighbor]
                    if len(new_string) % 2 == 0 or (len(new_string) % 2 == 1 and new_string[len(new_string)//2] == grid[neighbor][end]):
                        queue.append((neighbor, new_length))
                        visited.add(neighbor)
        return -1

    result = [[-1] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            result[i][j] = bfs(i, j)
    return result

# Read input
N = int(input().strip())
grid = [input().strip() for _ in range(N)]

# Calculate and print results
result = shortest_palindrome_path(N, grid)
for row in result:
    print(' '.join(map(str, row)))
